"""Latent switch whose combo lists input slot names instead of numbers."""

from __future__ import annotations

import logging


class WyslLatentSwitch:
    CATEGORY = "Wysl/工具"
    FUNCTION = "select_latent"
    RETURN_TYPES = ("LATENT",)
    RETURN_NAMES = ("latent",)
    DESCRIPTION = (
        "在多个 LATENT 输入之间切换。下拉框选项是输入接口的名称，"
        "不是 1、2、3。连上最后一个空接口会自动再增加一个接口，断开空接口会收回。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "select": (["latent1"], {"default": "latent1"}),
                "latent1": ("LATENT",),
            },
            "hidden": {"unique_id": "UNIQUE_ID", "extra_pnginfo": "EXTRA_PNGINFO"},
        }

    @classmethod
    def VALIDATE_INPUTS(cls, select, **kwargs):
        # 接口数量由前端动态增减，不能用静态 INPUT_TYPES 限制 select。
        return True

    @staticmethod
    def select_latent(select, unique_id=None, extra_pnginfo=None, **latents):
        selected = _resolve_selected_input(select, unique_id, extra_pnginfo, latents)
        if selected in latents:
            return (latents[selected],)
        logging.warning("WyslLatentSwitch: 选中的接口 %s 没有连接，回退到 latent1", selected)
        if "latent1" not in latents:
            raise ValueError("WyslLatentSwitch 至少需要连接 latent1")
        return (latents["latent1"],)


def _resolve_selected_input(select, unique_id, extra_pnginfo, latents):
    choice = str(select)
    if choice in latents:
        return choice
    if extra_pnginfo is None or unique_id is None:
        return "latent1"
    nodes = extra_pnginfo.get("workflow", {}).get("nodes", [])
    for node in nodes:
        if str(node.get("id")) != str(unique_id):
            continue
        for slot in node.get("inputs", []):
            name = slot.get("name")
            label = slot.get("label") or name
            if name in latents and (choice == name or choice == label):
                return name
        break
    return "latent1"


NODE_CLASS_MAPPINGS = {"WyslLatentSwitch": WyslLatentSwitch}
NODE_DISPLAY_NAME_MAPPINGS = {"WyslLatentSwitch": "Wysl-LatentSwitch"}
